INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @post_id,'_rank_math_description','راهنمای جامع انتخاب، خرید و نصب لوله نخی و تاشو (Layflat) برای انتقال آب در مزارع شهر پارود. بررسی ویژگی‌های فنی، سایزبندی، فشار کاری، جنس پلی‌اتیلن و نکات نگهداری بدون ایجاد ابهام.' WHERE @created_post=1 AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@post_id AND meta_key='_rank_math_description');
